third_round.probe_driver:
import json, os, pathlib, re, subprocess, tempfile, time
repo=pathlib.Path.cwd(); binary=str(repo/'pose-review'); base=pathlib.Path(tempfile.mkdtemp(prefix='b12-r3-')); results={'fixtures':str(base)}
def write(root,p,s):
 t=root/p;t.parent.mkdir(parents=True,exist_ok=True);t.write_text(s if isinstance(s,str) else json.dumps(s))
def run(root,*args):
 p=subprocess.run([binary,*args],cwd=root,capture_output=True,text=True);r={'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
 try:r['json']=json.loads(p.stdout)
 except ValueError:pass
 return r
def git(root):
 for args in [('init','-q'),('add','.'),('-c','user.name=Probe','-c','user.email=probe@example.invalid','-c','commit.gpgsign=false','commit','-qm','fixture')]:
  subprocess.run(['git','-C',str(root),*args],check=True,capture_output=True)
src=(repo/'pose-mcp/internal/cli/operation_results_test.go').read_text().split('files := map[string]string{',1)[1].split('\n\t}',1)[0]
for variant in ['readonly_recent','readonly_old','directory']:
 root=base/variant;root.mkdir()
 for m in re.finditer(r'"([^"\n]+)":\s*(`[^`]*`|"(?:[^"\\]|\\.)*")',src):
  v=m[2];write(root,m[1],v[1:-1] if v.startswith('`') else json.loads(v))
 target=root/'.pose/results/blocked.json';target.parent.mkdir(parents=True,exist_ok=True)
 if variant=='directory':target.mkdir()
 else:
  target.write_text('{"previous_run":true}\n');target.chmod(0o444)
  if variant=='readonly_old':os.utime(target,(time.time()-120,time.time()-120))
 git(root)
 # renew mtime just before operation; the previous file is still unwritable
