repo=pathlib.Path.cwd(); binary=str(repo/'pose-review'); base=pathlib.Path(tempfile.mkdtemp(prefix='b12-r5-')); results={'fixtures':str(base)}
def write(root,p,s):
 t=root/p;t.parent.mkdir(parents=True,exist_ok=True);t.write_text(s if isinstance(s,str) else json.dumps(s))
def run(root,*args):
 p=subprocess.run([binary,*args],cwd=root,capture_output=True,text=True);r={'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
 try:r['json']=json.loads(p.stdout)
 except ValueError:pass
 return r
def git(root):
 for args in [('init','-q'),('add','.'),('-c','user.name=Probe','-c','user.email=probe@example.invalid','-c','commit.gpgsign=false','commit','-qm','fixture')]:
  subprocess.run(['git','-C',str(root),*args],check=True,capture_output=True)
src=(repo/'pose-mcp/internal/cli/operation_results_test.go').read_text().split('files := map[string]string{',1)[1].split('\n\t}',1)[0]
for variant in ['readonly_recent','readonly_old','directory']:
 root=base/variant;root.mkdir()
 for m in re.finditer(r'"([^"\n]+)":\s*(`[^`]*`|"(?:[^"\\]|\\.)*")',src):
  v=m[2];write(root,m[1],v[1:-1] if v.startswith('`') else json.loads(v))
 target=root/'.pose/results/blocked.json';target.parent.mkdir(parents=True,exist_ok=True)
 if variant=='directory':target.mkdir()
 else:
  target.write_text('{"previous_run":true}\n');target.chmod(0o444)
  if variant=='readonly_old':os.utime(target,(time.time()-120,time.time()-120))
 git(root)
 # renew mtime just before operation; the previous file is still unwritable
 if variant=='readonly_recent':os.utime(target,None)
 before=target.read_bytes() if target.is_file() else None
 results[variant]={'plan':run(root,'close','spec:alpha','--plan','--json'),'apply':run(root,'close','spec:alpha','--apply','--reviewer','agent:reviewer','--json'),'previous_file_unchanged':before==target.read_bytes() if before else None}
 if target.is_file():target.chmod(0o644)
root=base/'start_partial';root.mkdir()
write(root,'.pose/policy/review.json',{'schema_version':1,'enabled':False,'atomic_start_version':1})
write(root,'.pose/specs/work.md','---\nslug: work\nstatus: draft\ncreated_at: 2026-09-27\n---\n\n# Spec: work\n\n## 2. Requirements\n\n- R1: Record the baseline.\n')
git(root)
plan=run(root,'start','spec:work','--json');(root/'.pose/specs').chmod(0o555)
results['start_partial']={'preview':plan,'apply':run(root,'start','spec:work','--apply','--digest',plan['json']['digest'],'--json')}
(root/'.pose/specs').chmod(0o755)
(root/'.pose/starts/work.json.tmp').mkdir()
results['start_partial']['retry_with_blocked_record_publish']=run(root,'start','spec:work','--apply','--digest',plan['json']['digest'],'--json')
results['start_partial']['human_retry_while_record_blocked']=run(root,'start','spec:work','--apply','--digest',plan['json']['digest'])
results['start_partial']['json_retry_while_record_blocked']=run(root,'start','spec:work','--apply','--digest',plan['json']['digest'],'--json')
(root/'.pose/starts/work.json.tmp').rmdir()
results['start_partial']['retry_after_repair']=run(root,'start','spec:work','--apply','--digest',plan['json']['digest'],'--json')
results['start_partial']['new_plan']=run(root,'start','spec:work','--json')
results['start_partial']['record']=json.loads((root/'.pose/starts/work.json').read_text());results['start_partial']['spec_after']=(root/'.pose/specs/work.md').read_text();(root/'.pose/specs').chmod(0o755)
(base/'results.json').write_text(json.dumps(results,indent=2));pathlib.Path('/tmp/b12-r5-extra.json').write_text(json.dumps(results,indent=2))
for k,v in results.items():
