receipt_contract_probe.test_source:
// Independent R2/R6 check: the first apply publishes the spec and fails only at the receipt.
func TestIndependentPublishedStartHasCompleteTypedReceipt(t *testing.T) {
 root := startCLIFixture(t, true)
 var plan posemodel.StartPlan
 if code, _ := runPoseJSON(t, root, &plan, "start", "spec:work", "--json"); code != 0 { t.Fatal("preview") }
 blocker := filepath.Join(root, ".pose", "starts", "work.json.tmp")
 if err := os.MkdirAll(blocker, 0755); err != nil { t.Fatal(err) }
 var result posemodel.OperationResult
 code, _ := runPoseJSON(t, root, &result, "start", "spec:work", "--apply", "--digest", plan.Digest, "--json")
 spec, err := os.ReadFile(filepath.Join(root, ".pose", "specs", "2026-09-27-work.md"))
 if err != nil || !strings.Contains(string(spec), "status: in-progress") || code != 1 || result.Step != "record" { t.Fatalf("bad fixture: %d %+v %v", code, result, err) }
 observed := false
 for _, effect := range result.Effects { if strings.Contains(effect.Ref, ".pose/specs/") { observed = true } }
 if !observed || len(result.StepsRun) == 0 { t.Fatalf("published spec is absent from typed effects or execution history: %+v", result) }
}

